29	     * from the right-most digit every second digit is doubled (subtracting 9 when the result
30	     * exceeds nine); the check digit is the amount needed to bring the running total to a
31	     * multiple of ten.
32	     */
33	    public static int checkDigit(String value) {
34	        int sum = 0;
