18	import java.time.LocalDate;
19	import java.time.Month;
20	
21	/**
22	 * Fiscal-year calendar rules. The fiscal year runs from 1 July to 30 June and is identified by
23	 * the calendar year in which it ends: a date on or after 1 July belongs to the fiscal year that
24	 * ends in the following calendar year (e.g. 18 September 2026 is in the fiscal year ending 2027).
25	 */
26	public final class FiscalYear {
27	
28	    /** The month on whose first day each fiscal year starts. */
29	    private static final Month START = Month.JULY;
30	
31	    private FiscalYear() {
32	    }
33	
34	    /**
35	     * The calendar year in which the fiscal year containing the given date ends. Dates on or after
36	     * 1 July belong to the fiscal year ending the following calendar year; earlier dates belong to
37	     * the one ending in their own calendar year.
38	     */
39	    public static int endingYear(LocalDate date) {
40	        return date.getMonthValue() >= START.getValue() ? date.getYear() + 1 : date.getYear();
41	    }
42	
43	    /**
44	     * The fiscal year of the given date formatted {@code 'FY<YY>'}, where YY is the last two digits
45	     * of its {@link #endingYear(LocalDate) ending year} (e.g. {@code 'FY27'}).
46	     */
47	    public static String label(LocalDate date) {
48	        return String.format("FY%02d", endingYear(date) % 100);
49	    }
50	
51	    /**
52	     * The number of whole fiscal years elapsed from {@code from} to {@code to}: the count of 1 July
53	     * boundaries crossed between the two dates. Two dates in the same fiscal year give 0.
54	     */
55	    public static long elapsed(LocalDate from, LocalDate to) {
56	        return endingYear(to) - endingYear(from);
57	    }
58	}
